// Package scan finds Dart/Flutter projects and measures what they can reclaim.
// It only reads the filesystem; nothing in this package deletes anything.
package scan

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// ArtifactDirs are the per-project directories flutterkill may reclaim,
// relative to the directory that holds pubspec.yaml (slash-separated).
// Every one of them is regenerated by flutter, pub, CocoaPods or Gradle on the
// next build. A directory only counts as an artifact when it sits at exactly
// this position next to a pubspec.yaml; names alone never match.
var ArtifactDirs = []string{
	"build",
	".dart_tool",
	"ios/Pods",
	"ios/.symlinks",
	"macos/Pods",
	"android/.gradle",
	"android/app/.cxx",
}

// IsArtifactDir reports whether rel (slash-separated) is one of ArtifactDirs.
func IsArtifactDir(rel string) bool {
	for _, a := range ArtifactDirs {
		if rel == a {
			return true
		}
	}
	return false
}

// Artifact is one reclaimable directory inside a project.
type Artifact struct {
	Name  string `json:"name"` // relative to the project, e.g. "ios/Pods"
	Path  string `json:"path"`
	Bytes int64  `json:"bytes"` // -1 until measured
}

// Project is a directory containing a pubspec.yaml.
type Project struct {
	Name           string     `json:"name"`
	Path           string     `json:"path"`
	Flutter        bool       `json:"flutter"`
	FVMVersion     string     `json:"fvm_version,omitempty"`
	LastActivity   time.Time  `json:"last_activity"`
	ActivitySource string     `json:"activity_source"` // "git", "mtime" or "" if unknown
	Artifacts      []Artifact `json:"artifacts"`
}

// Bytes is the total measured size of the project's artifacts.
func (p *Project) Bytes() int64 {
	var n int64
	for _, a := range p.Artifacts {
		if a.Bytes > 0 {
			n += a.Bytes
		}
	}
	return n
}

// FindProjects walks root and returns every Dart/Flutter project (directory
// with a pubspec.yaml), including those without artifacts. Artifact sizes and
// activity are left unset. Unreadable directories are skipped silently.
func FindProjects(root string) ([]*Project, error) {
	var projects []*Project
	isProject := map[string]bool{}
	home, _ := os.UserHomeDir()

	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			if path == root {
				return err
			}
			return fs.SkipDir
		}
		if !d.IsDir() {
			return nil
		}
		if path != root && skipDir(path, d.Name(), isProject) {
			return fs.SkipDir
		}
		// A stray ~/pubspec.yaml must not turn ~/build into an artifact.
		if path == home || !isRegularFile(filepath.Join(path, "pubspec.yaml")) {
			return nil
		}
		isProject[path] = true
		projects = append(projects, newProject(root, path))
		return nil
	})
	sort.Slice(projects, func(i, j int) bool { return projects[i].Path < projects[j].Path })
	return projects, err
}

// skipDir decides whether the walk should not descend into dir.
func skipDir(dir, name string, isProject map[string]bool) bool {
	// Hidden dirs (.git, .dart_tool, .gradle, .fvm, ...), npm installs and
	// CocoaPods never contain projects we want to report.
	if strings.HasPrefix(name, ".") || name == "node_modules" || name == "Pods" {
		return true
	}
	// Artifacts of an already-found project, e.g. <project>/build.
	for _, a := range ArtifactDirs {
		rel := filepath.FromSlash(a)
		if strings.HasSuffix(dir, string(filepath.Separator)+rel) && isProject[strings.TrimSuffix(dir, string(filepath.Separator)+rel)] {
			return true
		}
	}
	return isFlutterSDK(dir)
}

// isFlutterSDK spots a Flutter SDK checkout: its packages are not the user's
// projects, and its caches are managed by the SDK itself.
func isFlutterSDK(dir string) bool {
	return isRegularFile(filepath.Join(dir, "bin", "internal", "engine.version")) ||
		(isRegularFile(filepath.Join(dir, "bin", "flutter")) && isRegularFile(filepath.Join(dir, "packages", "flutter_tools", "pubspec.yaml")))
}

func newProject(root, dir string) *Project {
	p := &Project{Path: dir, Name: filepath.Base(dir), Artifacts: []Artifact{}}
	readPubspec(p)
	p.FVMVersion = fvmVersion(root, dir)
	for _, a := range ArtifactDirs {
		path := filepath.Join(dir, filepath.FromSlash(a))
		if RealDirBelow(dir, path) == nil && !HoldsSourceTopLevel(path) {
			p.Artifacts = append(p.Artifacts, Artifact{Name: a, Path: path, Bytes: -1})
		}
	}
	return p
}

// RealDirBelow checks that target is a directory strictly inside base and that
// no path component after base (target included) is a symlink.
func RealDirBelow(base, target string) error {
	rel, err := filepath.Rel(base, target)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		return fmt.Errorf("%s is outside %s", target, base)
	}
	cur := base
	for _, part := range strings.Split(rel, string(filepath.Separator)) {
		cur = filepath.Join(cur, part)
		fi, err := os.Lstat(cur)
		if err != nil {
			return err
		}
		if fi.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("refusing symlink %s", cur)
		}
		if !fi.IsDir() {
			return fmt.Errorf("%s is not a directory", cur)
		}
	}
	return nil
}

// HoldsSourceTopLevel reports whether dir directly contains a pubspec.yaml or
// .git, i.e. looks like someone's project rather than generated output.
func HoldsSourceTopLevel(dir string) bool {
	for _, name := range []string{"pubspec.yaml", ".git"} {
		if _, err := os.Lstat(filepath.Join(dir, name)); err == nil {
			return true
		}
	}
	return false
}

// TrackedFile returns a file under dir that git tracks, or "" if there is
// none (or dir is not in a git repo). Generated output is never committed, so
// a hit means the directory holds real work. Build output may legitimately
// contain pubspec.yaml or .git (e.g. Swift Package Manager checkouts in
// build/ios/SourcePackages), so those alone are not a signal below the top level.
func TrackedFile(dir string) string {
	out, err := gitCmd(dir, "ls-files", "-z", "--", ".").Output()
	if err != nil {
		return ""
	}
	if first, _, _ := strings.Cut(string(out), "\x00"); first != "" {
		return filepath.Join(dir, filepath.FromSlash(first))
	}
	return ""
}

// readPubspec fills the package name and whether it depends on Flutter. A
// line scan is enough for these two fields and avoids a YAML dependency.
func readPubspec(p *Project) {
	f, err := os.Open(filepath.Join(p.Path, "pubspec.yaml"))
	if err != nil {
		return
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	for s.Scan() {
		line := s.Text()
		if v, ok := strings.CutPrefix(line, "name:"); ok {
			if v = strings.Trim(strings.TrimSpace(v), `"'`); v != "" {
				p.Name = v
			}
		}
		if strings.TrimSpace(line) == "sdk: flutter" {
			p.Flutter = true
		}
	}
}

// fvmVersion returns the Flutter version pinned with FVM (.fvmrc for FVM 3,
// .fvm/fvm_config.json for FVM 2) in dir or its parents up to root, or "".
func fvmVersion(root, dir string) string {
	for d := dir; ; d = filepath.Dir(d) {
		if v := fvmPin(d); v != "" {
			return v
		}
		if d == root || d == filepath.Dir(d) || !strings.HasPrefix(d, root) {
			return ""
		}
	}
}

func fvmPin(dir string) string {
	var cfg struct {
		Flutter           string `json:"flutter"`
		FlutterSdkVersion string `json:"flutterSdkVersion"`
	}
	for _, name := range []string{".fvmrc", filepath.Join(".fvm", "fvm_config.json")} {
		b, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil || json.Unmarshal(b, &cfg) != nil {
			continue
		}
		if cfg.Flutter != "" {
			return cfg.Flutter
		}
		if cfg.FlutterSdkVersion != "" {
			return cfg.FlutterSdkVersion
		}
	}
	return ""
}

func isRegularFile(path string) bool {
	fi, err := os.Lstat(path)
	return err == nil && fi.Mode().IsRegular()
}
